import { pgTable, text, timestamp, uuid } from 'drizzle-orm/pg-core'
import { user } from './auth-schema.gen'

// auth-schema is generated by @better-auth/cli when running generate (Better Auth speaks Drizzle)
export * from './auth-schema.gen'

// Additional schema definitions can be added here
export const clothingItem = pgTable('clothing_item', {
  id: uuid('id')
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  type: text('type', { enum: ['shirt', 'pants'] }).notNull(),
  name: text('name').notNull(),
  color: text('color'),
  brand: text('brand'),
  size: text('size'),
  imageUrl: text('image_url'),
  notes: text('notes'),
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at')
    .$onUpdate(() => new Date())
    .notNull()
    .defaultNow(),
})
